class Solution {
public:
    int countLetters(string s) {
        int total = 0, streak = 0;
        char prev = ' ';
        for (char c : s) {
            if (c == prev) {
                streak++;
            } else {
                streak = 1;
                prev = c;
            }
            total += streak;
        }
        return total;
    }
};

class Solution {
    public int countLetters(String s) {
        int total = 0, streak = 0;
        char prev = ' ';
        for (char c : s.toCharArray()) {
            if (c == prev) {
                streak++;
            } else {
                streak = 1;
                prev = c;
            }
            total += streak;
        }
        return total;
    }
}

var countLetters = function(s) {
    let total = 0, streak = 0;
    let prev = '';
    for (const c of s) {
        if (c === prev) {
            streak++;
        } else {
            streak = 1;
            prev = c;
        }
        total += streak;
    }
    return total;
};
